import pytest
import cart

# Helper for approximate equality when rounding matters

def assert_close(a, b):
    assert round(a,2) == round(b,2)

# Test apply_discount spec
@pytest.mark.parametrize("price,percent,result",[
    (200,15,170.0),
    (100,0,100.0),
    (50,100,0.0),
])
def test_apply_discount(price,percent,result):
    assert cart.apply_discount(price,percent) == result

@pytest.mark.parametrize("price,percent",[(-10,5),(50,-1),(50,101)])
def test_apply_discount_invalid(price,percent):
    with pytest.raises(ValueError):
        cart.apply_discount(price,percent)

# bulk_discount_percent
@pytest.mark.parametrize("qty,expected",[
    (9,0), (10,5), (49,5), (50,10), (99,10), (100,15), (200,15),
])
def test_bulk_discount(qty,expected):
    assert cart.bulk_discount_percent(qty) == expected

@pytest.mark.parametrize("qty",[0,-1,3.5])
def test_bulk_discount_invalid(qty):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(qty)

# parse_coupon
valid_codes = ["SAVE10","save20 ","  SaVe30"]
for code in valid_codes:
    assert cart.parse_coupon(code) == int(code.strip().upper()[4:])

@pytest.mark.parametrize("code",["SAVEX","SAVE-5","  SAVE51  "])
def test_parse_coupon_invalid(code):
    with pytest.raises(ValueError):
        cart.parse_coupon(code)

# shipping_fee
@pytest.mark.parametrize("subtotal,member,result",[
    (0,False,60),
    (999.99,False,60),
    (1000,False,0),
    (500,True,30),
])
def test_shipping(subtotal,member,result):
    assert cart.shipping_fee(subtotal,member) == result

@pytest.mark.parametrize("subtotal",[-1,-10])
def test_shipping_invalid(subtotal):
    with pytest.raises(ValueError):
        cart.shipping_fee(subtotal)

# Cart functionality tests
def test_cart_add_and_items():
    c = cart.Cart()
    c.add_item('apple', 0.5, 3)
    assert c.items() == {'apple':3}
    # Add same item with same price
    c.add_item('apple', 0.5, 2)
    assert c.items() == {'apple':5}
    # Adding new item
    c.add_item('banana',1.0,1)
    assert set(c.items().keys())=={'apple','banana'}

@pytest.mark.parametrize("name",["pear","orange"])
def test_remove_nonexistent(name):
    c=cart.Cart()
    with pytest.raises(KeyError):
        c.remove_item(name)

def test_cart_remove_and_quantity():
    c = cart.Cart()
    c.add_item('apple',0.5,5)
    c.remove_item('apple',2)
    assert c.items()=={'apple':3}
    # remove remaining
    c.remove_item('apple',3)
    assert c.items()=={}

def test_cart_subtotal_with_bulk_discount():
    c = cart.Cart()
    c.add_item('item1', 10, 5)   # qty 5 -> no discount
    c.add_item('item2', 20, 10)  # qty10 -> 5% discount
    # subtotal before bulk: 5*10 + 10*20 = 50+200=250
    # apply discounts: item1 unchanged, item2 discounted by 5% => 190
    expected = 50 + 190
    assert c.subtotal() == round(expected,2)

@pytest.mark.parametrize("coupon,total",[
    ('SAVE10',0),  # empty cart
])
def test_cart_total_empty(coupon,total):
    c=cart.Cart()
    assert c.total(member=False,coupon=coupon)==total

# total with coupon and shipping

def test_cart_total_with_coupon_and_shipping():
    c=cart.Cart()
    c.add_item('widget',100,1)  # subtotal 100
    # subtotal after coupon SAVE10 -> 90
    # shipping on 90: not free, member=False => 60
    expected = round(90+60,2)
    assert c.total(member=False,coupon='SAVE10') == expected

# total for members (half shipping) and no coupon

def test_cart_total_member_no_coupon():
    c=cart.Cart()
    c.add_item('gadget',200,1)
    # subtotal 200, no coupon
    # shipping on 200: member True => 30
    assert c.total(member=True,coupon=None)==230.0

# total free shipping threshold

def test_cart_total_free_shipping():
    c=cart.Cart()
    c.add_item('expensive',1000,1)
    # subtotal 1000, no coupon => free shipping
    assert c.total(member=False,coupon=None)==1000.0

# invalid coupon raises ValueError in total

def test_cart_total_invalid_coupon():
    c=cart.Cart()
    with pytest.raises(ValueError):
        c.total(member=False,coupon='BADCODE')

